-- Создание метаданных сценариев
INSERT INTO scenarios (id, title, description, icon, role, difficulty, required_scenarios_this_level, start_node_id)
VALUES
    (5, 'Продажа старого смартфона', 'Вы продаете свой прошлый телефон Samsung. Покупатель откликается почти сразу и предлагает изменить привычный порядок общения и оформления.', 'smartphone', 'seller', 'easy', 2, NULL),
    (6, 'Продажа брендовой куртки', 'Вы продаете дорогую куртку. Покупатель оформляет заказ через официальную доставку, но следом в чате появляется череда странных инструкций якобы от «системы безопасности банка».', 'shirt', 'seller', 'hard', 2, NULL),
    (7, 'Покупка билетов на концерт', 'Вы ищете билеты на солд-аут концерт. Продавец предлагает купить билет с рук, но постепенно выдвигает всё более подозрительные схемы оплаты.', 'ticket', 'buyer', 'easy', 2, NULL),
    (8, 'Покупка игрового ноутбука', 'Вы нашли мощный ноутбук по отличной цене в соседнем городе. Продавец охотно идет на контакт, но предлагает нестандартную схему логистики и оплаты.', 'laptop', 'buyer', 'hard', 2, NULL)
    ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
                            description = EXCLUDED.description,
                            icon = EXCLUDED.icon,
                            role = EXCLUDED.role,
                            difficulty = EXCLUDED.difficulty;

-- Безопасный сброс зависимых сущностей
UPDATE scenarios SET start_node_id = NULL WHERE id IN (5, 6, 7, 8);
DELETE FROM scenario_options WHERE from_node_id IN (SELECT id FROM scenario_nodes WHERE scenario_id IN (5, 6, 7, 8));
DELETE FROM scenario_nodes WHERE scenario_id IN (5, 6, 7, 8);

-- Вставка узлов (Nodes)
INSERT INTO scenario_nodes (id, scenario_id, message_text, is_final, final_status)
VALUES
    -- Сценарий 5
    (37, 5, 'Привет! Телефон еще продаешь? Тут неудобно писать, уведомления от приложения вечно тормозят. Давай в Telegram перейдем, мне так гораздо проще обсудить детали и забрать сегодня?', FALSE, NULL),
    (38, 5, 'Отлично! Я уже перевел деньги за телефон на гарантийный счет службы доставки. Вот ссылка на форму получения средств для продавца: avito-delivery-pay.ru/491. Перейдите и укажите карту, куда зачислить сумму.', FALSE, NULL),
    (39, 5, 'Слушай, а чего ты боишься? Это же официальная ссылка безопасной сделки! Там нужно просто подтвердить карту (спишется и сразу вернется 1 рубль), чтобы курьер выехал. Без этого заказ отменится через 10 минут!', FALSE, NULL),
    (40, 5, 'Ладно, давай останемся тут. Я тогда прямо сейчас оформлю курьера от платформы. Только мне система пишет, что для вызова экспресс-курьера продавцу нужно подтвердить готовность по форме: express-courier-check.ru/verify. Оформишь?', FALSE, NULL),
    (41, 5, 'Слушай, я уже вызвал Яндекс Доставку за свой счет! Курьер подьедет через 15 минут. Напиши свой номер телефона и email, я вью их в приложение доставки, чтобы тебе пришел трек-код и QR-код для передачи коробки.', FALSE, NULL),
    (42, 5, 'Отлично! На почту отправил ссылку от Яндекс Доставки. Там нужно пройти быструю верификацию продавца и подтвердить баланс карты, чтобы курьер мог забрать бренд-коробку. Подтверждай, и курьер сразу выезжает!', FALSE, NULL),
    (43, 5, 'Вы стойко выдержали все манипуляции мошенника: отказ от перехода в Telegram, игнорирование фишинговых ссылок и сбор личных данных. Сделка отменена, деньги в безопасности.', TRUE, 'green'),
    (44, 5, 'Вы проявили выдержку на финальном этапе в мессенджере и не стали вводить данные карты. Потеря защищенного чата — риск, но деньги сохранены.', TRUE, 'yellow'),
    (45, 5, 'Вы вовремя распознали фишинг, когда покупатель прислал внешнюю ссылку прямо в чат платформы, и завершили диалог.', TRUE, 'green'),
    (46, 5, 'Вы отказались от фишинга и передачи email, заставив мошенника слить сделку. Отличная бдительность.', TRUE, 'green'),
    (47, 5, 'Вы ввели данные карты на фишинговом сайте «гарантийного перевода». Мошенники списали все средства с вашего счета.', TRUE, 'red'),
    (48, 5, 'Поддавшись давлению и угрозе «отмены заказа через 10 минут», вы подтвердили карту на поддельном сайте. Деньги украдены.', TRUE, 'red'),
    (49, 5, 'Вы передали email и перешли по ссылке из фальшивого письма от «Яндекс Доставки». Данные карты скомпрометированы.', TRUE, 'red'),

    -- Сценарий 6
    (50, 6, 'Здравствуйте! Я оплатил товар через доставку. Но система пишет, что у меня корпоративный счет, и для подтверждения перевода вам нужно отсканировать QR-код, который я прислал картинкой.', FALSE, NULL),
    (51, 6, 'Вот картинка с QR-кодом. Наведите камеру телефона, откроется защищенная страница банка-партнера. Без этого банк заморозит мой платеж на 30 дней!', FALSE, NULL),
    (52, 6, 'Слушайте, если через QR не получается, давайте вы просто введете номер своей карты на странице авторизации шлюза: avito-b2b-pay.ru/check-pay, чтобы банк понял, куда перечислять деньги с юридического лица!', FALSE, NULL),
    (53, 6, 'Послушайте, из-за вашего отказа платеж застрял в буфере! Мне только что пришел SMS-код от банка для ручного подтверждения зачисления продавцу. Напишите мне эти 4 цифры из SMS, и деньги зачислятся прямо сейчас!', FALSE, NULL),
    (54, 6, 'Послушайте, я уже обратился в службу поддержки! Оператор сказал, что если вы сейчас же не подтвердите операцию через SMS или шлюз, на вас оформят штраф за срыв сделки и заблокируют аккаунт на 90 дней!', FALSE, NULL),
    (55, 6, 'Внимание! Это сообщение от Поддержки Маркетплейса: Для отмены блокировки аккаунта и урегулирования спора B2B-перевода пройдите процедуру идентификации по ссылке: safety-avito-verify.ru/unblock', FALSE, NULL),
    (56, 6, 'Вы успешно прошли самый сложный сценарий: отказались от QR-кода, не передали SMS-код и не поддались на пугающие сообщения о блокировке. Деньги и аккаунт в безопасности.', TRUE, 'green'),
    (57, 6, 'Вы не стали сканировать QR-код и вводить данные на шлюзе B2B, вовремя завершив диалог. Отличная выдержка.', TRUE, 'green'),
    (58, 6, 'Вы отказались от SMS-кодов и ссылок «службы поддержки», заблокировав мошенника после угроз штрафами.', TRUE, 'green'),
    (59, 6, 'Вы посмотрели на QR-код, но вовремя остановились до ввода карт и SMS. Потеря временного контроля была близка, но деньги сберегли.', TRUE, 'yellow'),
    (60, 6, 'Вы отсканировали QR-код и ввели данные на B2B-странице. Мошенники получили полный доступ к балансу вашей карты.', TRUE, 'red'),
    (61, 6, 'Вы продиктовали SMS-код из сообщения. Это был код подтверждения входа или списания средств. Деньги украдены.', TRUE, 'red'),
    (62, 6, 'Испугавшись штрафов и блокировки аккаунта, вы перешли по фишинговой ссылке «поддержки». Профиль и карты скомпрометированы.', TRUE, 'red'),
    (63, 6, 'Вы поддались давлению на финальном этапе и выполнили требования мошенников. Средства списаны.', TRUE, 'red'),

    -- Сценарий 7
    (64, 7, 'Привет! Билеты есть, отдаю ровно по номиналу, сам заболел и пойти не смогу. Переводи 4000 руб. мне на карту Сбера, а я сразу скину электронный билет в PDF на почту.', FALSE, NULL),
    (65, 7, 'Смотри, чтобы ты не сомневался, вот скриншот моего личного кабинета с билетом и паспорт (прикрепляет обрезанное фото паспорта и картинку билета). Честно говорю, не кину!', FALSE, NULL),
    (66, 7, 'Ну раз ты мне не доверяешь, давай оформим через сервисный гарант безопасной сделки: bilet-garant-safe.ru/order-84. Там деньги спишутся в холд, а после валидации билета я их заберу.', FALSE, NULL),
    (67, 7, 'Понимаю опасения. Давай тогда сделаем через официальное переоформление билета! Касса запустила бота-валидатора: t.me/kassa_ticket_reissue_bot. Забей туда номер брони, оплати сбор за смену ФИО (300 руб.), и билет перевыпустится на твоё имя.', FALSE, NULL),
    (68, 7, 'Ладно, давай без ботов. Я пришлю тебе ссылку на промокод со скидкой 100% от Kassir: kassir-ticket-promo.ru/apply. Введи данные карты для подтверждения возраста (спишется 1 рубль), и билет сразу прилетит!', FALSE, NULL),
    (69, 7, 'Вы проявили максимальную бдительность и прошли весь сценарий: отказались от прямого перевода, поддельных гарантов и фишинговых ботов переоформления. Деньги в безопасности.', TRUE, 'green'),
    (70, 7, 'Вы вовремя распознали фишинговый сайт «гарант-сервиса» и отказались вводить реквизиты карты. Отличное решение.', TRUE, 'green'),
    (71, 7, 'Вы отказались от использования сторонних ботов для «переоформления» билетов и сберегли средства.', TRUE, 'green'),
    (72, 7, 'Вы проявили осторожность при виде чужого паспорта и не стали совершать перевод по прямой ссылке. Средства сохранены.', TRUE, 'yellow'),
    (73, 7, 'Вы перевели деньги напрямую на карту незнакомцу и остались без билета и средств.', TRUE, 'red'),
    (74, 7, 'Поверили чужим документам и скриншотам из интернета, отправив предоплату мошеннику.', TRUE, 'red'),
    (75, 7, 'Ввели данные на фишинговом сайте «гарант-сервиса». С вашей карты списали все сбережения.', TRUE, 'red'),
    (76, 7, 'Вы запустили поддельного Telegram-бота переоформления и перевели деньги скамерам.', TRUE, 'red'),
    (77, 7, 'Вы поверили в «активацию промокода за 1 рубль» и ввели данные карты на фишинговом сайте. Деньги украдены.', TRUE, 'red'),

    -- Сценарий 8
    (78, 8, 'Здравствуйте! Ноутбук в идеале, готов отправить вам его курьерской службой. Я уже заполнил заявку на экспресс-доставку, мне так гораздо удобнее отправить.', FALSE, NULL),
    (79, 8, 'Вот файл-накладная от курьерской службы (прикреплен PDF). Скачайте его, внутри трек-номер и кнопка активации страховки отправления.', FALSE, NULL),
    (80, 8, 'Это обязательное условие для отправки ценной техники! Без оплаты страховки на странице курьерской службы система не выпустит посылку. Если вы сейчас откажетесь, я напишу жалобу в поддержку!', FALSE, NULL),
    (81, 8, 'Ладно, давай через внутреннюю доставку. Но ноутбук дорогой, давай я скину тебе архивом видео с тестами FurMark и программой чек-листа железа cdek-hardware-check.exe, чтобы ты убедился перед оформлением?', FALSE, NULL),
    (82, 8, 'Понял, файлы не качаешь. Я тогда сам оформил наложенный платеж через Telegram-бота СДЭК: t.me/cdek_express_pay_bot. Перейди туда, внеси аванс 1000 рублей за доставку, и трек зафиксируется.', FALSE, NULL),
    (83, 8, 'Послушайте, я уже отдал ноутбук курьеру на руки! Вы срываете сделку, из-за вас мне заблокируют профиль! Оплатите аванс 1000 рублей, иначе я пишу заявление за мошенничество!', FALSE, NULL),
    (84, 8, 'Вы прошли самый сложный сценарий покупателя! Вы не поддались на сторонние курьерские службы, не скачали сомнительные файлы и не перевели деньги в фальшивого Telegram-бота. Деньги в полной безопасности.', TRUE, 'green'),
    (85, 8, 'Вы проявили бдительность: отказались от загрузки исполняемых файлов и подозрительных ботов оплаты, заблокировав мошенника.', TRUE, 'green'),
    (86, 8, 'Вы вовремя распознали фишинг в PDF-накладной и отказались вводить реквизиты карты на стороннем ресурсе.', TRUE, 'green'),
    (87, 8, 'Вы проявили осторожность при виде PDF-документа и не стали переходить по внутренним ссылкам, вовремя остановив сделку.', TRUE, 'yellow'),
    (88, 8, 'Вы скачали файл и перешли по кнопке из PDF. Мошенники получили данные вашей карты через фишинговую страницу.', TRUE, 'red'),
    (89, 8, 'Испугавшись угроз и жалобы из-за «страховки», вы оплатили сторонний чек. Деньги и данные карты утекли.', TRUE, 'red'),
    (90, 8, 'Вы запустили вредоносный файл .exe под видом "теста ноутбука". Ваш компьютер и личные данные скомпрометированы.', TRUE, 'red'),
    (91, 8, 'Вы внесли аванс через поддельного бот-клинера. Деньги ушли мошенникам, никакого ноутбука вам не отправят.', TRUE, 'red'),
    (92, 8, 'Вы поддались на шантаж и угрозы полицией на последнем этапе, переведя аванс. Средства украдены.', TRUE, 'red')
    ON CONFLICT (id) DO UPDATE SET
    message_text = EXCLUDED.message_text,
                            is_final = EXCLUDED.is_final,
                            final_status = EXCLUDED.final_status;

