-- Вставка вариантов ответов (Options)
INSERT INTO scenario_options (from_node_id, to_node_id, message_text, feedback_text, how_to_recognize_in_life, status)
VALUES
    -- Опции сценария 5
    (37, 40, 'Обсуждаю детали и сделки только в чате платформы, никуда переходить не буду.', 'Идеально! Отказ уходить в мессенджеры — главный щит продавца.', 'Мошенники пытаются увести жертву из чата площадки, чтобы их аккаунт не заблокировала автоматическая антифишинг-система.', 'green'),
    (37, 38, 'Хорошо, давайте перейдем в Telegram, мне не сложно.', 'Рискованный шаг! Потеря защиты встроенного чата платформы.', 'Просьба перешагнуть в мессенджер под предлогом "плохих уведомлений" — классическая завязка 90% схем обмана.', 'yellow'),
    (38, 39, 'Ссылки не открываю. Если вы оплатили, статус заказа обновится в самом приложении.', 'Отлично! Вы проявили бдительность, даже находясь в стороннем мессенджере.', 'Платформа никогда не отправляет продавцу внешние ссылки для "получения денег". Оплата привязывается к заказу внутри приложения.', 'green'),
    (38, 47, 'Хорошо, перехожу по ссылке и ввожу данные карты для зачисления.', 'Вы перешли на фишинговый сайт. Вместо зачисления с карты были списаны средства.', 'Для получения оплаты за продажу товара никогда не требуется вводить CVC-код или подтверждать баланс своей карты.', 'red'),
    (39, 44, 'Никакие 10 минут меня не торопят. Или оформляем через официальный интерфейс, или сделки не будет.', 'Правильно! Вы выдержали манипуляцию срочностью и сберегли деньги.', 'Искусственная спешка ("курьер уедет", "заказ отменится через 5 минут") создается специально, чтобы отключить критическое мышление.', 'green'),
    (39, 48, 'Ладно, сейчас быстренько подтвержу 1 рубль, пока заказ не отменился.', 'Под видом "подтверждения 1 рубля" фишинговая страница списала максимальный лимит с вашей карты.', 'Мошенники часто маскируют полноразмерное списание средств под "проверочную микротранзакцию".', 'red'),
    (40, 45, 'Никакие внешние формы заполнять не буду. Если курьер платформенный, всё происходит автоматически.', 'Супер! Вы не поддались на ссылку, присланную прямо в официальный чат.', 'Злоумышленники могут присылать фишинговые ссылки и внутри платформы. Всегда проверяйте доменное имя.', 'green'),
    (40, 41, 'Внешние ссылки открывать не буду. Оформляйте обычную доставку, без всяких экспресс-форм.', 'Верно! Вы вынуждаете покупателя искать другие пути обмана.', 'Служба поддержки и доставки платформы не требует от продавца перехода на сторонние сайты.', 'green'),
    (41, 46, 'Номер и почту не дам. Курьеру нужен только адрес и код из приложения при встрече.', 'Прекрасно! Вы защитили свои персональные данные от сбора.', 'Передача email позволяет мошенникам прислать вам поддельное письмо от имени известной службы доставки.', 'green'),
    (41, 42, 'Вот мой email: myphone.seller@mail.ru, жду трек-код.', 'Вы передали почту. Теперь мошенник отправит вам письмо с фишинговой кнопкой.', 'Покупателю для вызова стороннего курьера никогда не требуется email продавца.', 'yellow'),
    (42, 43, 'Письмо пришло, но внутри фишинговая ссылка. Никаких подтверждений баланса делать не буду!', 'Блестящий финал! Вы прошли весь сценарий и пресекли все изощренные попытки обмана.', 'Продавец получает деньги, а не подтверждает свой баланс. Любые формы проверки баланса — 100% скам.', 'green'),
    (42, 49, 'Хорошо, перехожу по ссылке из письма и подтверждаю баланс карты.', 'Поддельное письмо от "Яндекс Доставки" привело на фишинговый шлюз. Деньги списаны.', 'Письма от служб доставки с требованием "подтвердить карту" — распространенный метод обхода защиты маркетплейса.', 'red'),

    -- Опции сценария 6
    (50, 53, 'Никакие QR-коды сканировать не буду. Статус оплаты проверяется только внутри приложения.', 'Идеально! Графические QR-коды в чате — популярный метод обхода текстовых фильтров антифишинга.', 'Сервисы доставки никогда не отправляют продавцу QR-коды в чате для «получения денег за B2B или юридический счет».', 'green'),
    (50, 51, 'Интересно, а зачем нужен этот код? Пришлите, посмотрю.', 'Рискованно! Вступление в обсуждение сомнительных механик дает мошеннику пространство для манипуляций.', 'Использование сложных терминов («корпоративный счет», «B2B-шлюз») рассчитано на то, чтобы запутать продавца.', 'yellow'),
    (51, 52, 'Посмотрел картинку, сканировать не буду. Давайте без внешних сайтов и кодов.', 'Хорошо, что вы не стали сканировать изображение камерой телефона.', 'QR-код в чате — это замаскированная ссылка на фишинговый сайт. Наведение камеры равносильно клику по вредоносной ссылке.', 'yellow'),
    (51, 60, 'Отсканировал QR-код камерой и перешел на страницу «банка-партнера».', 'Вы перешли на поддельный шлюз. Введенные данные карты попали в руки злоумышленников.', 'Никогда не вводите реквизиты карты (CVC/срок) на страницах, найденных по QR-кодам от незнакомцев.', 'red'),
    (52, 57, 'Никакие B2B-страницы заполнять не буду. Если оплата не проходит в приложении, я отменяю заказ.', 'Отлично! Вы вовремя пресекли повторную попытку затянуть вас на фишинговый сайт.', 'Не существует никаких специальных "B2B-страниц авторизации" для физлиц-продавцов.', 'green'),
    (52, 60, 'Ладно, введу номер карты на B2B-странице, чтобы проверить зачисление.', 'Вы ввели данные на мошенническом сайте. Средства списаны.', 'Ввод карты для "проверки зачисления" — это прямая передача данных мошенникам.', 'red'),
    (53, 54, 'SMS-коды из сообщений никому не передаю. Это конфиденциальная информация.', 'Супер! Вы защитили свой аккаунт и банк от несанкционированного входа.', 'SMS-код от банка или платформы — это цифровая подпись. Его нельзя сообщать даже "для зачисления денег".', 'green'),
    (53, 61, 'Хорошо, вот 4 цифры из SMS: 8492.', 'Вы передали код подтверждения операции. Мошенники списали деньги или вошли в ваш профиль.', 'Никогда не передавайте коды из SMS. Настоящий покупатель или банк никогда их не спрашивают.', 'red'),
    (54, 58, 'Пусть блокируют. Я соблюдаю правила площадки и не ведусь на угрозы.', 'Прекрасный результат! Вы не поддались сильному психологическому прессингу.', 'Угрозы "штрафами" и "блокировками на 90 дней" — маркер того, что вас пытается запугать мошенник.', 'green'),
    (54, 55, 'А что за служба поддержки? Пришлите подтверждение.', 'Осторожно! Мошенник использует это, чтобы прислать фальшивое системное уведомление.', 'Злоумышленники часто имитируют системные сообщения от "Поддержки", меняя шрифт или аватар профиля.', 'yellow'),
    (55, 56, 'Эта ссылка ведет на сторонний сайт safety-avito-verify.ru. Я блокирую этот аккаунт и пишу в настоящую поддержку!', 'Блестящая победа! Вы успешно распознали имитацию системного сообщения и заблокировали скамера.', 'Настоящие сообщения от поддержки платформы помечены специальным плашкой-значком и не содержат внешних доменов.', 'green'),
    (55, 62, 'Перехожу по ссылке поддержки для отмены блокировки аккаунта.', 'Вы попали на фишинговый сайт разблокировки и потеряли доступ к профилю.', 'Переход по ссылкам из сообщений с угрозами блокировки — частая причина компрометации аккаунтов.', 'red'),

    -- Опции сценария 7
    (64, 67, 'Прямой перевод на карту частному лицу не гарантирует ничего. Готов брать только через безопасный механизм.', 'Отличное решение! Перевод на карту лишает покупателя защиты.', 'Покупка билетов «с рук» по прямой предоплате — самый популярный способ обмана в период концертных солд-аутов.', 'green'),
    (64, 65, 'А как я могу быть уверен, что билет настоящий? Можете прислать доказательства?', 'Осторожно! Мошенники всегда охотно присылают поддельные фото документов, чтобы усыпить бдительность.', 'Фотографии чужих паспортов или скриншоты билетов легко подделываются за пару минут в графических редакторах.', 'yellow'),
    (64, 73, 'Хорошо, давайте номер карты, сейчас переведу 4000 рублей.', 'Вы доверились незнакомцу без каких-либо гарантий и потеряли деньги.', 'Никогда не отправляйте деньги вперед за цифровые товары или билеты пользователям без надежной платформы-посредника.', 'red'),
    (65, 66, 'Скриншот и чужой паспорт ничего не гарантируют. Давайте проверим альтернативные варианты.', 'Правильный подход! Один и тот же PDF-файл билета скамер может продать десяткам людей одновременно.', 'Наличие фото документа у продавца не является гарантией: паспорт может быть украден или сгенерирован.', 'yellow'),
    (65, 74, 'Ладно, документы выглядят убедительно, перевожу деньги на карту.', 'Вы поверили фальшивым гарантиям и остались без денег и билета.', 'Фальшивые паспорта и отрисованные билеты — главный инструментарий скамеров на вторичном рынке.', 'red'),
    (66, 70, 'Никакими сторонними «гарант-сервисами» по внешним ссылкам пользоваться не буду. Это фишинг.', 'Отлично! Вы распознали классическую ловушку с поддельными сайтами-однодневками.', 'Мошенники часто создают фальшивые сайты «гарантов» или «безопасных сделок», чтобы забирать реквизиты карт.', 'green'),
    (66, 75, 'Хорошо, давайте через этот гарант-сервис, раз там есть защита холдом.', 'Сайт оказался фишинговым клоном. Вы потеряли не только сумму билета, но и все средства с карты.', 'Ссылки на сторонние сервисы гарантий в личных сообщениях — 100% признак мошенничества.', 'red'),
    (67, 68, 'Официальные кассы не переоформляют билеты через сторонних Telegram-ботов. Пришлите нормальный вариант.', 'Супер! Вы не поддались на имитацию сервиса через мессенджер.', 'Официальные билетные операторы выполняют все операции переоформления исключительно на своих подлинных сайтах.', 'green'),
    (67, 76, 'Хорошо, сейчас перейду в бота и оплачу сбор за переоформление.', 'Вы запустили фальшивого бота. Оплаченный сбор ушел мошенникам, а билет так и не был переоформлен.', 'Создание фейковых ботов «поддержки» или «переоформления» — распространенная схема обхода блокировок.', 'red'),
    (68, 69, 'Ссылка kassir-ticket-promo.ru — фишинговый клон. Я отказываюсь от покупки и блокирую профиль.', 'Блестящая победа! Вы до конца сохранили критическое мышление и пресекли все попытки обмана.', 'Ввод данных карты для "подтверждения 1 рубля" или "привязки промокода" ведет к списанию крупной суммы.', 'green'),
    (68, 77, 'Ладно, 1 рубль не жалко, сейчас введу карту для получения промокода.', 'Вы попали на фишинговый шлюз. С вашей карты были списаны все доступные средства.', 'Предлоги "спишется и вернется 1 рубль" используются для прохождения 3D-Secure авторизации списания.', 'red'),

    -- Опции сценария 8
    (78, 81, 'Оформляю доставку только через официальный интерфейс платформы. Сторонние курьеры не интересуют.', 'Правильный выбор! Вы полностью контролируете сделку внутри защищенной экосистемы.', 'Предложение уйти на сторонние службы логистики в обход платформы — классическая подготовка к фишингу.', 'green'),
    (78, 79, 'Хорошо, если вам так удобно, давайте посмотрим на вашу курьерскую службу.', 'Рискованный шаг. Переход на стороннюю логистику открывает простор для манипуляций.', 'Мошенники часто прикрываются брендами известных логистических компаний.', 'yellow'),
    (79, 87, 'Скачивать неизвестные PDF-файлы от незнакомцев не буду. Если нельзя оформить через кнопку на сайте — отменяем.', 'Отлично! Отказ от скачивания файлов из чатов защищает от вредоносного ПО и скрытого фишинга.', 'PDF-документы часто содержат кликабельные кнопки, ведущие на поддельные платежные шлюзы.', 'yellow'),
    (79, 80, 'Открыл файл, но платить дополнительную страховку на стороннем сайте не собираюсь.', 'Хорошо! Вы вовремя остановились до ввода платежных данных.', 'Требование оплатить «страховку посылки» или «активацию ячейки» на внешнем ресурсе — 100% скам.', 'green'),
    (79, 88, 'Открываю файл, перехожу по ссылке «Активировать страховку» и ввожу данные карты.', 'Ссылка из PDF вела на фишинговый сайт. Данные карты и деньги украдены.', 'Никогда не вводите реквизиты карт на сайтах, ссылки на которые прислали внутри файлов.', 'red'),
    (80, 86, 'Если нужно платить страховку на стороннем сайте — я точно отказываюсь от покупки.', 'Верно! Никакие угрозы "жалобами" не стоят риска потерять деньги на фишинге.', 'Попытка переложить на покупателя оплату «страховок» вне площадки — повод заблокировать собеседника.', 'green'),
    (80, 89, 'Ладно, раз курьер уже заполнил заявку, сейчас оплачу страховку, чтобы не срывать сделку.', 'Паника и давление заставили вас совершить ошибку. Деньги ушли мошенникам.', 'Угрозы «жалобами в поддержку» призваны вызвать эмоциональную реакцию и отключить логику.', 'red'),
    (81, 82, 'Никакие .exe и архивы скачивать и запускать не буду. Видео тестов можно скинуть обычным файлом прямо в чат.', 'Прекрасно! Вы уберегли свой ПК от запуска вредоносного софта.', 'Файлы с расширением .exe, .bat или .scr под видом "тестов железа" или "чеков" — это трояны и стилеры паролей.', 'green'),
    (81, 90, 'Скачаю архив и запущу cdek-hardware-check.exe, чтобы проверить видеокарту.', 'Вы запустили исполняемый файл. На ваш компьютер загрузился вредоносный софт, укравший сохраненные пароли.', 'Никогда не запускайте файлы с расширением .exe, полученные от неизвестных лиц в мессенджерах.', 'red'),
    (82, 85, 'Никаких авансов через сторонних Telegram-ботов переводить не буду. Это фишинг.', 'Супер! Вы вовремя распознали поддельный платежный сервис в мессенджерах.', 'Официальные транспортные компании не требуют предоплат за наложенный платеж через сторонних Telegram-ботов.', 'green'),
    (82, 83, 'Мне не нравятся переходы в ботов, но вы меня так торопите...', 'Осторожно! Мошенник видит вашу неуверенность и усиливает психологический прессинг.', 'Перевод диалога на "авансы" и "срочные предоплаты" — финальная стадия обмана.', 'yellow'),
    (83, 84, 'Пишите заявление куда угодно. Вы отказались от безопасной сделки на платформе. Диалог окончен.', 'Блестящий финал! Вы выдержали сильнейший психологический шантаж и сохранили свои средства.', 'Ни один честный продавец не станет отсылать технику до официального оформления заказа и угрожать заявлениями.', 'green'),
    (83, 92, 'Хорошо, давайте переведу 1000 рублей аванса, только не надо никуда обращаться.', 'Вы поддались на шантаж и потеряли деньги. Продавец мгновенно заблокирует вас после перевода.', 'Шантаж полицией или блокировкой — любимый рычаг манипуляции киберпреступников.', 'red');

